function AgentStepsScene({
  query = "A 30-second launch video for an analytics dashboard",
  steps:
    stepsInput = "Searching the registry… > Searched the registry @globe; Looking up components matching “dashboard”… > Looked up 6 matching components; Reading the docs… > Read 4 component docs @globe; Checking available props… > Checked available props; Building the timeline… > Set 9 scene timings; Rendering frames… > Rendered frames",
  result = "Rendered 900 frames",
  queryHold = 0.683,
  stepHold = 0.45,
  finalHold = 0.283,
  paperColor,
  glowColor,
  glowX = 0.858,
  glowY = 0.854,
  glowRadius = 0.465,
  pillColor,
  inkColor,
  stepColor,
  accentColor,
  centerY = 0.5,
  fontFamily,
  theme: themeOverride,
  mode,
  speed = 1,
}: AgentStepsProps) {
  const frame = useCurrentFrame();
  const { fps, height, width } = useVideoConfig();
  const t = useKitTheme(themeOverride, mode);
  const face = resolveFont(fontFamily ?? t.fontFamily) ?? SANS;
  const steps = toSteps(stepsInput);

  const fc = frame * speed;
  const paper = paperColor ?? t.background;
  const pill = pillColor ?? t.card;
  const ink = inkColor ?? t.foreground;
  const muted = stepColor ?? t.mutedForeground;
  const accent = accentColor ?? t.primary;
  // The wash is the accent at a sixth strength — a tint of the page, never a
  // second colour on it. mixOklch, not an alpha, so it survives a render onto a
  // frame that has no compositing behind it.
  const glow = glowColor ?? mixOklch(paper, accent, 0.17);

  const pitch = ROW_PITCH * height;
  const font = FONT * height;
  const iconSize = ICON * height;
  const shiftF = SHIFT_S * fps;

  const holds = steps.map((s) => (s.hold ?? stepHold) * fps);
  const { steps: sched, outro } = schedule(
    holds,
    queryHold * fps,
    finalHold * fps,
  );
  const lastIndex = steps.length - 1;

  // --- the column ----------------------------------------------------------

  const offset = columnOffset(
    fc,
    sched.map((s) => s.enter),
    shiftF,
  );
  const outroP = ramp(fc, outro, OUTRO_SCALE_S * fps);
  const scale = interpolate(OUTRO_EASE(outroP), [0, 1], [1, OUTRO_SCALE]);
  // How far the running row has slid from the column's left edge to the frame's
  // centre. Expressed as two percentage translates (see the JSX) so it needs no
  // measurement of either width.
  const centred = OUTRO_EASE(ramp(fc, outro, OUTRO_POS_S * fps));
  // Everything that has already finished clears; the running row does not.
  const settledOpacity =
    1 - OUTRO_FADE_EASE(ramp(fc, outro, OUTRO_FADE_S * fps));

  const intro = ramp(fc, 0, INTRO_S * fps);
  const introE = Easing.out(Easing.cubic)(intro);
  const introBlur =
    INTRO_BLUR *
    height *
    (1 - Easing.out(Easing.cubic)(ramp(fc, 0, INTRO_BLUR_S * fps)));

  const handoff = ramp(fc, outro + HANDOFF_AT * fps, HANDOFF_S * fps);
  const resultIn = ramp(fc, outro + RESULT_AT * fps, RESULT_S * fps);
  const glint = ramp(fc, outro + GLINT_AT * fps, GLINT_S * fps);

  const rowStyle = {
    height: pitch,
    display: "flex",
    alignItems: "center",
    gap: ICON_GAP * height,
    whiteSpace: "nowrap",
    flexShrink: 0,
  } as const;

  const label = {
    fontFamily: face,
    fontSize: font,
    fontWeight: 400,
    lineHeight: 1,
    letterSpacing: "0em",
  } as const;

  return (
    <AbsoluteFill
      showInTimeline={false}
      style={{ backgroundColor: paper, overflow: "hidden" }}
    >
      {glowRadius > 0 ? (
        <AbsoluteFill
          showInTimeline={false}
          style={{
            background: `radial-gradient(circle ${glowRadius * height}px at ${glowX * width}px ${glowY * height}px, ${glow} 0%, ${paper} 100%)`,
            opacity: introE,
          }}
        />
      ) : null}

      <AbsoluteFill
        showInTimeline={false}
        style={{
          alignItems: "center",
          justifyContent: "flex-start",
        }}
      >
        {/* The column. Its width is the widest row's — the query pill, in
            practice — so centring it centres the pill and leaves every step
            left-aligned to the pill's left edge, which is what the reference
            does. The scale pivots on the column's horizontal centre and on the
            running row's baseline row, so the finished rows spread away from
            the one line that is staying put. */}
        <div
          style={{
            position: "absolute",
            top: centerY * height - pitch / 2,
            display: "inline-flex",
            flexDirection: "column",
            alignItems: "flex-start",
            transform: `translateY(${-offset * pitch}px) scale(${scale})`,
            transformOrigin: `50% ${(offset + 0.5) * pitch}px`,
          }}
        >
          <div
            style={{
              ...rowStyle,
              opacity: introE * settledOpacity,
              filter: introBlur > 0.01 ? `blur(${introBlur}px)` : undefined,
              transform: `scale(${interpolate(introE, [0, 1], [INTRO_SCALE, 1])})`,
            }}
          >
            <div
              style={{
                ...label,
                fontSize: font * QUERY_FONT_SCALE,
                // The prompt reads a step heavier than the log it starts. It is
                // the one line on screen the user wrote.
                fontWeight: 500,
                color: ink,
                background: pill,
                height: PILL_H * height,
                borderRadius: PILL_R * PILL_H * height,
                padding: `0 ${PILL_PAD * PILL_H * height}px`,
                display: "flex",
                alignItems: "center",
              }}
            >
              {query}
            </div>
          </div>

          {steps.map((step, i) => {
            const s = sched[i];
            if (fc <= s.enter) return null;
            const isDone = fc >= s.done;
            const isLast = i === lastIndex;
            const opacity =
              Easing.out(Easing.cubic)(ramp(fc, s.enter, ROW_FADE_S * fps)) *
              (isLast ? 1 - handoff : settledOpacity);
            const showCheck = isDone && (step.icon ?? "check") === "check";
            return (
              <div
                // biome-ignore lint/suspicious/noArrayIndexKey: the log is a fixed ordered list, so the index is the identity
                key={i}
                style={{
                  ...rowStyle,
                  width: "100%",
                  opacity,
                  // Only the running row travels, and only during the outro.
                  transform: isLast
                    ? `translateX(${50 * centred}%)`
                    : undefined,
                }}
              >
                {/* The step Studio selects is this inner row: it shrinks to
                    the icon and label, where the outer row spans the column. */}
                <Item index={i}>
                  <div
                    style={{
                      ...rowStyle,
                      height: pitch,
                      transform: isLast
                        ? `translateX(${-50 * centred}%)`
                        : undefined,
                    }}
                  >
                    {showCheck ? (
                      <Check
                        size={iconSize}
                        color={accent}
                        strokeWidth={CHECK_W}
                      />
                    ) : (
                      <div style={{ opacity: isDone ? 1 : RUNNING_ICON }}>
                        <Globe
                          size={iconSize}
                          color={muted}
                          strokeWidth={GLOBE_W}
                          turn={isDone ? 0 : (fc / (SPIN_S * fps)) % 1}
                        />
                      </div>
                    )}
                    {/* The running label is *not* dimmed. Measured: the ref's
                        running and done labels carry the same ink per glyph
                        (ratio 1.04, which is the two strings' own width ratio).
                        Only the icon is faint while a step runs. */}
                    <span style={{ ...label, color: muted }}>
                      {isDone ? step.done : step.running}
                    </span>
                  </div>
                </Item>
              </div>
            );
          })}
        </div>
      </AbsoluteFill>

      {/* The result. Its own layer, centred on the frame rather than on the
          column, because by the time it lands there is no column left to
          align to. */}
      {resultIn > 0 ? (
        <AbsoluteFill
          showInTimeline={false}
          style={{ alignItems: "center", justifyContent: "center" }}
        >
          <div
            style={{
              position: "absolute",
              top: centerY * height - (RESULT_PILL_H * height) / 2,
              display: "flex",
              alignItems: "center",
              gap: ICON_GAP * RESULT_FONT_SCALE * height,
              height: RESULT_PILL_H * height,
              padding: `0 ${RESULT_PAD * PILL_H * height}px`,
              borderRadius: PILL_R * RESULT_PILL_H * height,
              background: pill,
              opacity: resultIn,
              overflow: "hidden",
              whiteSpace: "nowrap",
            }}
          >
            {/* A glint, not a shine: one soft disc of the accent crossing the
                chip once. It is the only moment in the scene with any colour
                behind the type, so it has to be over before it is noticed. */}
            {glint > 0 && glint < 1 ? (
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  background: `radial-gradient(circle ${GLINT_R * height}px at ${glint * 130 - 15}% 50%, ${accent} 0%, transparent 100%)`,
                  opacity:
                    0.22 *
                    interpolate(glint, [0, 0.08, 0.85, 1], [0, 1, 1, 0], CLAMP),
                }}
              />
            ) : null}
            <Check
              size={iconSize * RESULT_FONT_SCALE}
              color={accent}
              strokeWidth={CHECK_W}
            />
            <span
              style={{
                ...label,
                fontSize: font * RESULT_FONT_SCALE,
                fontWeight: 500,
                color: ink,
                position: "relative",
              }}
            >
              {result}
            </span>
          </div>
        </AbsoluteFill>
      ) : null}
    </AbsoluteFill>
  );
}

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio: one step at a time
   ───────────────────────────────────────────────────────────────────────── */

/**
 * Everything `el` paints that can be seen, in page pixels: its text runs, its
 * media, and every box with a fill or a border, each cut to every box that
 * clips it up to and including `root` (the Element's own box). Null when none
 * of it shows — transparent, or clipped out of the Element.
 */
function AgentStepsPainted(
  el: Element,
  root: Element,
): [number, number, number, number] | null {
  let u: [number, number, number, number] | null = null;
  const add = (r: DOMRect, from: Element) => {
    // Never past the Element's own box, clipped or not: a text run's line box
    // stands above its ink, and no scene's ink leaves its box (measured).
    const c0 = root.getBoundingClientRect();
    let b: [number, number, number, number] = [
      Math.max(r.left, c0.left),
      Math.max(r.top, c0.top),
      Math.min(r.right, c0.right),
      Math.min(r.bottom, c0.bottom),
    ];
    let alpha = 1;
    for (
      let a: Element | null = from;
      a;
      a = a === root ? null : a.parentElement
    ) {
      const cs = getComputedStyle(a);
      if (cs.visibility === "hidden") return;
      alpha *= Number(cs.opacity);
      if (a !== from && a !== root && cs.overflow !== "visible") {
        const c = a.getBoundingClientRect();
        b = [
          Math.max(b[0], c.left),
          Math.max(b[1], c.top),
          Math.min(b[2], c.right),
          Math.min(b[3], c.bottom),
        ];
      }
    }
    if (alpha < 0.02 || b[2] <= b[0] || b[3] <= b[1]) return;
    u = u
      ? [
          Math.min(u[0], b[0]),
          Math.min(u[1], b[1]),
          Math.max(u[2], b[2]),
          Math.max(u[3], b[3]),
        ]
      : b;
  };
  const walk = (e: Element) => {
    const cs = getComputedStyle(e);
    if (cs.display === "none") return;
    const media = /^(img|video|canvas|svg)$/i.test(e.tagName);
    if (
      media ||
      cs.backgroundColor !== "rgba(0, 0, 0, 0)" ||
      cs.backgroundImage !== "none" ||
      parseFloat(cs.borderTopWidth) > 0
    )
      add(e.getBoundingClientRect(), e);
    if (media) return;
    for (const n of Array.from(e.childNodes)) {
      if (n.nodeType === Node.TEXT_NODE && n.textContent?.trim()) {
        const range = document.createRange();
        range.selectNodeContents(n);
        for (const r of Array.from(range.getClientRects())) add(r, e);
      } else if (n.nodeType === Node.ELEMENT_NODE) walk(n as Element);
    }
  };
  walk(el);
  return u;
}

/** Whether every box that clips `el`, up to `root`, leaves all of it showing. */
function AgentStepsWhole(el: Element, root: Element): boolean {
  const r = el.getBoundingClientRect();
  for (let a = el.parentElement; a; a = a === root ? null : a.parentElement) {
    if (getComputedStyle(a).overflow === "visible") continue;
    const c = a.getBoundingClientRect();
    if (
      r.left < c.left - 1 ||
      r.top < c.top - 1 ||
      r.right > c.right + 1 ||
      r.bottom > c.bottom + 1
    )
      return false;
  }
  return true;
}
type AgentStepsStepValues = {
  readonly running?: string;
  readonly done?: string;
  readonly icon?: string;
};

type AgentStepsStepProps = InteractiveBaseProps &
  Omit<InteractiveTransformProps, "style"> &
  AgentStepsStepValues & {
    readonly style?: CSSProperties | null;
    /** The node the scene draws this step as, while it draws it; set by the stage, never by hand. */
    readonly claim?: { current: Element | null };
    /** The box its outline falls back to when the node is not all there; set by the stage too. */
    readonly slot?: { current: HTMLDivElement | null };
    /** Hands Studio's live props back to the stage, which draws the node; set by the stage too. */
    readonly report?: (state: AgentStepsStepState) => void;
  };

/** What Studio is doing to one step right now, which the stage applies to its node. */
type AgentStepsStepState = {
  values: AgentStepsStepValues;
  style?: CSSProperties;
  hidden?: boolean;
  from?: number;
  durationInFrames?: number;
};

const AgentStepsStepSchema = {
  ...Interactive.baseSchema,
  running: { type: "text-content", default: "", description: "While running" },
  done: {
    type: "text-content",
    default: "",
    description: "When done (the last step never is)",
  },
  icon: {
    type: "enum",
    default: "check",
    description: "Icon when done",
    variants: { check: {}, globe: {} },
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

/**
 * One step: its layer in Studio. The scene decides where it is on every
 * frame and draws it; this is the Sequence Studio lists, selects and outlines,
 * mounted for the Element's whole length so the layer never leaves the
 * timeline while the step is off the frame. It draws nothing itself: its
 * values, transform, visibility and timing reach the node through the stage.
 */
const AgentStepsStepInner = forwardRef<
  Element,
  AgentStepsStepProps & { readonly controls: SequenceControls | undefined }
>(
  (
    {
      controls,
      name,
      style,
      from,
      durationInFrames,
      trimBefore,
      playbackRate,
      loop,
      freeze,
      hidden,
      showInTimeline,
      claim,
      slot,
      report,
      running,
      done,
      icon,
    },
    ref,
  ) => {
    // What Studio outlines, chosen every frame: the node itself — its exact
    // quad, transforms and all — while all of it shows; a box over the part
    // that does when the Element clips it or it paints past its own box; nothing while none of it
    // shows, so an object that has left is not still selectable where it was.
    const target = useRef<Element | null>(null);
    // Re-rendered every frame, so the outline is chosen for every frame: the
    // scene moves the node without re-rendering this layer.
    useCurrentFrame();
    // Studio reads the ref every time it measures.
    const outline = useRef({
      get current() {
        return target.current ?? claim?.current ?? null;
      },
    }).current;
    // Studio's live props arrive here — a value being typed, a transform being
    // dragged, the layer hidden or retimed — and the stage draws the node.
    useLayoutEffect(() => {
      report?.({
        values: { running, done, icon },
        style: style ?? undefined,
        hidden,
        from,
        durationInFrames,
      });
    });
    useImperativeHandle(ref, () => claim?.current as Element);
    useLayoutEffect(() => {
      // Outlines are a Studio thing; a render or the Player measures nothing.
      if (!getRemotionEnvironment().isStudio) return;
      const box = slot?.current;
      const root = box?.parentElement;
      if (!box || !root) return;
      const el = claim?.current;
      const b = el ? AgentStepsPainted(el, root) : null;
      if (!el || !b) {
        box.style.display = "none";
        target.current = box;
        return;
      }
      const n = el.getBoundingClientRect();
      if (
        AgentStepsWhole(el, root) &&
        b[0] >= n.left - 1 &&
        b[1] >= n.top - 1 &&
        b[2] <= n.right + 1 &&
        b[3] <= n.bottom + 1
      ) {
        box.style.display = "none";
        target.current = el;
        return;
      }
      const r = root.getBoundingClientRect();
      const k = root.offsetWidth / (r.width || 1);
      box.style.display = "block";
      box.style.left = `${(b[0] - r.left) * k}px`;
      box.style.top = `${(b[1] - r.top) * k}px`;
      box.style.width = `${(b[2] - b[0]) * k}px`;
      box.style.height = `${(b[3] - b[1]) * k}px`;
      target.current = box;
    });
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        playbackRate={playbackRate}
        loop={loop}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Step"}
        controls={controls}
        outlineRef={outline}
      />
    );
  },
);

const AgentStepsStep = Interactive.withSchema({
